// Assuming the following helper function is defined in the project
// char *generate_filter_graph_dot(RSFilter *filter);

void visualize_filter_graph(RSFilter *filter) {
    if (!filter) {
        fprintf(stderr, "Warning: Invalid filter provided.\n");
        return;
    }

    char *dot_content = generate_filter_graph_dot(filter);
    if (!dot_content) {
        fprintf(stderr, "Warning: Failed to generate DOT representation.\n");
        return;
    }

    char dot_filename[] = "/tmp/filter_graph_XXXXXX.dot";
    int fd = mkstemp(dot_filename);
    if (fd == -1) {
        free(dot_content);
        fprintf(stderr, "Warning: Failed to create temporary file.\n");
        return;
    }

    FILE *dot_file = fdopen(fd, "w");
    if (!dot_file) {
        close(fd);
        free(dot_content);
        fprintf(stderr, "Warning: Failed to open temporary file.\n");
        return;
    }

    fprintf(dot_file, "%s", dot_content);
    fclose(dot_file);
    free(dot_content);

    char png_filename[] = "/tmp/filter_graph_XXXXXX.png";
    if (mktemp(png_filename) == NULL) {
        unlink(dot_filename);
        fprintf(stderr, "Warning: Failed to create temporary PNG filename.\n");
        return;
    }

    char command[512];
    snprintf(command, sizeof(command), "dot -Tpng %s -o %s", dot_filename, png_filename);

    int status = system(command);
    if (WIFSIGNALED(status) || WEXITSTATUS(status) != 0) {
        fprintf(stderr, "Warning: Conversion to PNG failed.\n");
        unlink(dot_filename);
        unlink(png_filename);
        return;
    }

    snprintf(command, sizeof(command), "gnome-open %s", png_filename);
    status = system(command);
    if (WIFSIGNALED(status) || WEXITSTATUS(status) != 0) {
        fprintf(stderr, "Warning: Failed to open generated PNG file.\n");
    }

    unlink(dot_filename);
}

