#include <sys/stat.h>
#include <sys/types.h>

// Assuming RSFilter and generate_dot_representation are defined elsewhere in the codebase
// and generate_dot_representation is a helper function that returns a dynamically allocated string.

void visualize_filter_graph(RSFilter *filter) {
    if (!filter) {
        return; // Invalid filter, exit early
    }

    char *dot_content = generate_dot_representation(filter);
    if (!dot_content) {
        free(dot_content); // Safety first
        return;
    }

    char dot_file_path[256];
    char png_file_path[256];

    // Generate temporary file names
    int dot_fd = g_tempnam(dot_file_path, "filter_graph");
    snprintf(dot_file_path, sizeof(dot_file_path), "/tmp/filter_graph_dot_%d.dot", getpid());
    snprintf(png_file_path, sizeof(png_file_path), "/tmp/filter_graph_dot_%d.png", getpid());

    FILE *dot_file = fopen(dot_file_path, "w");
    if (!dot_file) {
        perror("Failed to open DOT file for writing");
        free(dot_content);
        return;
    }

    fprintf(dot_file, "%s", dot_content);
    fclose(dot_file);
    free(dot_content);

    // Convert DOT file to PNG using the dot command
    char dot_cmd[512];
    snprintf(dot_cmd, sizeof(dot_cmd), "dot -Tpng %s -o %s", dot_file_path, png_file_path);
    int dot_result = system(dot_cmd);

    if (dot_result != 0) {
        fprintf(stderr, "Failed to convert DOT to PNG\n");
        return;
    }

    // Open the PNG file using gnome-open
    char open_cmd[512];
    snprintf(open_cmd, sizeof(open_cmd), "gnome-open %s", png_file_path);
    int open_result = system(open_cmd);

    if (open_result != 0) {
        fprintf(stderr, "Failed to open generated PNG file\n");
    }

    // Clean up the temporary files
    unlink(dot_file_path);
    unlink(png_file_path);
}

