#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>
#include <stdio.h>
#include <errno.h>

// Assuming RSFilter and related helper functions are defined elsewhere in the codebase.
// Function to generate a DOT representation of the filter graph.
char *generate_dot_graph(RSFilter *filter);

void visualize_filter_graph(RSFilter *filter) {
    if (!filter) {
        return; // Invalid filter, do nothing
    }

    // Generate the DOT representation
    char *dot_content = generate_dot_graph(filter);
    if (!dot_content) {
        return; // Failed to generate DOT content
    }

    // Generate temporary file names for DOT and PNG files
    char dot_filename[] = "/tmp/filter_graph_XXXXXX.dot";
    char png_filename[] = "/tmp/filter_graph_XXXXXX.png";
    int dot_fd = mkstemp(dot_filename);
    if (dot_fd == -1) {
        free(dot_content);
        return;
    }

    // Write the DOT content to the file
    FILE *dot_file = fdopen(dot_fd, "w");
    if (!dot_file) {
        close(dot_fd);
        free(dot_content);
        return;
    }
    fprintf(dot_file, "%s", dot_content);
    fclose(dot_file);
    free(dot_content);

    // Use the `dot` command to convert to PNG
    char *dot_cmd = "dot -Tpng ";
    char *dot_to_png_cmd = malloc(strlen(dot_cmd) + strlen(dot_filename) + strlen(png_filename) + 1);
    if (!dot_to_png_cmd) {
        return; // Memory allocation failed
    }

    snprintf(dot_to_png_cmd, strlen(dot_cmd) + strlen(dot_filename) + strlen(png_filename) + 1,
             "%s -o %s %s", dot_cmd, png_filename, dot_filename);

    int dot_status = system(dot_to_png_cmd);
    free(dot_to_png_cmd);

    if (dot_status == -1 || WIFEXITED(dot_status) && WEXITSTATUS(dot_status) != 0) {
        fprintf(stderr, "Failed to convert DOT to PNG: %s\n", strerror(errno));
        return;
    }

    // Open the generated PNG using `gnome-open`
    char *open_cmd = "gnome-open ";
    char *open_png_cmd = malloc(strlen(open_cmd) + strlen(png_filename) + 1);
    if (!open_png_cmd) {
        return; // Memory allocation failed
    }

    snprintf(open_png_cmd, strlen(open_cmd) + strlen(png_filename) + 1, "%s%s", open_cmd, png_filename);

    int open_status = system(open_png_cmd);
    free(open_png_cmd);

    if (open_status == -1 || WIFEXITED(open_status) && WEXITSTATUS(open_status) != 0) {
        fprintf(stderr, "Failed to open PNG file: %s\n", strerror(errno));
        return;
    }
}
